108	/**
109	 * Evaluates the outcome of a user confirmation and dispatches
110	 * policy config updates.
111	 */
112	export async function updatePolicy(
113	  tool: AnyDeclarativeTool,
114	  outcome: ToolConfirmationOutcome,
115	  confirmationDetails: SerializableConfirmationDetails | undefined,
116	  context: AgentLoopContext,
117	  toolInvocation?: AnyToolInvocation,
118	): Promise<void> {
119	  const deps = { ...context, toolInvocation };
120	
121	  // Mode Transitions (AUTO_EDIT)
122	  if (isAutoEditTransition(tool, outcome)) {
123	    deps.config.setApprovalMode(ApprovalMode.AUTO_EDIT);
124	    return;
125	  }
126	
127	  // Determine persist scope if we are persisting.
128	  let persistScope: 'workspace' | 'user' | undefined;
129	  if (outcome === ToolConfirmationOutcome.ProceedAlwaysAndSave) {
130	    // If folder is trusted and workspace policies are enabled, we prefer workspace scope.
131	    if (
132	      deps.config.isTrustedFolder() &&
133	      deps.config.getWorkspacePoliciesDir() !== undefined
134	    ) {
135	      persistScope = 'workspace';
136	    } else {
137	      persistScope = 'user';
138	    }
139	  }
140	
141	  // Specialized Tools (MCP)
142	  if (confirmationDetails?.type === 'mcp') {
143	    await handleMcpPolicyUpdate(
144	      tool,
145	      outcome,
146	      confirmationDetails,
147	      deps.messageBus,
148	      persistScope,
149	    );
150	    return;
151	  }
152	
153	  // Generic Fallback (Shell, Info, etc.)
154	  await handleStandardPolicyUpdate(
155	    tool,
156	    outcome,
157	    confirmationDetails,
158	    deps.messageBus,
159	    persistScope,
160	    deps.toolInvocation,
161	    deps.config,
162	  );
163	}
